-- Base64 decoder
local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local b64lookup = {}
for i = 1, #b64chars do b64lookup[string.sub(b64chars, i, i)] = i - 1 end

local function base64Decode(data)
    if not data or data == "" then return "" end
    if crypt and crypt.base64decode then return crypt.base64decode(data) end
    if syn and syn.base64decode then return syn.base64decode(data) end
    if base64decode then return base64decode(data) end
    data = string.gsub(data, "[^" .. b64chars .. "=]", "")
    local result = {}
    local i = 1
    while i <= #data do
        local a = b64lookup[string.sub(data, i, i)] or 0
        local b = b64lookup[string.sub(data, i + 1, i + 1)] or 0
        local c = b64lookup[string.sub(data, i + 2, i + 2)] or 0
        local d = b64lookup[string.sub(data, i + 3, i + 3)] or 0
        local n = a * 262144 + b * 4096 + c * 64 + d
        local c1 = math.floor(n / 65536) % 256
        local c2 = math.floor(n / 256) % 256
        local c3 = n % 256
        table.insert(result, string.char(c1))
        if string.sub(data, i + 2, i + 2) ~= "=" then
            table.insert(result, string.char(c2))
        end
        if string.sub(data, i + 3, i + 3) ~= "=" then
            table.insert(result, string.char(c3))
        end
        i = i + 4
    end
    return table.concat(result)
end

