function Lucide.GetAsset(iconName, iconSize)
    if type(iconName) ~= "string" then
        error("Lucide.GetAsset: Argument 1 (iconName): expected type string", 2)
    end
    local name = string.match(string.lower(iconName), "^%s*(.*)%s*$") or iconName
    if cache[name] then return cache[name] end

    local b64data = IconData[name]
    if not b64data then
        error("Lucide.GetAsset: Failed to find icon: " .. name, 2)
    end

    local getasset = getcustomasset or getsynasset
    if not getasset or not writefile then return nil end

    local fileName = CACHE_DIR .. "/" .. name .. ".png"

    -- Check local cache first
    if isfile and isfile(fileName) then
        local ok, assetUrl = pcall(getasset, fileName)
        if ok and assetUrl then
            local result = {
                IconName = name,
                Url = assetUrl,
            }
            cache[name] = result
            return result
        end
    end

    -- Decode base64 and write PNG
    local pngData = base64Decode(b64data)
    if not pngData or #pngData < 50 then return nil end

    if isfolder and not isfolder(CACHE_DIR) then
        pcall(makefolder, CACHE_DIR)
    end

    local ok = pcall(writefile, fileName, pngData)
    if not ok then return nil end

    local ok2, assetUrl = pcall(getasset, fileName)
    if ok2 and assetUrl then
        local result = {
            IconName = name,
            Url = assetUrl,
        }
        cache[name] = result
        return result
    end

    return nil
end

function Lucide.ImageLabel(iconName, iconSize, props)
    iconSize = iconSize or 256
    local asset = Lucide.GetAsset(iconName, iconSize)
    if not asset then return nil end
    local label = Instance.new("ImageLabel")
    label.Name = asset.IconName
    label.Size = UDim2.fromOffset(iconSize, iconSize)
    label.BackgroundColor3 = Color3.new(0, 0, 0)
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    label.Image = asset.Url
    label.ImageColor3 = Color3.new(1, 1, 1)
    label.ScaleType = Enum.ScaleType.Fit
    if props then
        for k, v in pairs(props) do
            if k ~= "Parent" then label[k] = v end
        end
        if props.Parent then label.Parent = props.Parent end
    end
    return label
end

